-- 032_paper_operation_metadata: persist the last server-authenticated training-paper operator.
-- Historical rows remain NULL; creator identity and timestamps are not rewritten.

-- @step paper_updated_by
-- @replaces-check 031_paper_sort_order/paper_sort_order
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_paper') = 24 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_paper' AND ((COLUMN_NAME = 'regulation_id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'business_scope' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'regulation') OR (COLUMN_NAME = 'mode' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'fixed') OR (COLUMN_NAME = 'category_id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'requires_learning' AND COLUMN_TYPE = 'tinyint unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = '1') OR (COLUMN_NAME IN ('regulation_ids', 'course_ids', 'rule_config') AND DATA_TYPE = 'json' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL))) = 8 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_paper' AND INDEX_NAME = 'idx_paper_training_pool' AND ((SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'category_id') OR (SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'business_scope') OR (SEQ_IN_INDEX = 3 AND COLUMN_NAME = 'mode') OR (SEQ_IN_INDEX = 4 AND COLUMN_NAME = 'status')) AND NON_UNIQUE = 1 AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) = 4 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='exam_paper' AND COLUMN_NAME='designer_layout' AND DATA_TYPE='json' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='')=1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='exam_paper' AND ((COLUMN_NAME='required_learning_minutes' AND DATA_TYPE='int' AND COLUMN_TYPE='int unsigned' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='' AND GENERATION_EXPRESSION='' AND COLUMN_COMMENT='') OR (COLUMN_NAME='remark' AND DATA_TYPE='varchar' AND COLUMN_TYPE='varchar(1000)' AND CHARACTER_SET_NAME='utf8mb4' AND COLLATION_NAME='utf8mb4_0900_ai_ci' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='' AND GENERATION_EXPRESSION='' AND COLUMN_COMMENT='')))=2 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='exam_paper' AND COLUMN_NAME='course_ids' AND COLUMN_COMMENT='考前学习课程关联，不参与抽题过滤')=1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='exam_paper' AND COLUMN_NAME='sort_order' AND DATA_TYPE='int' AND COLUMN_TYPE='int' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT='0' AND EXTRA='' AND GENERATION_EXPRESSION='' AND COLUMN_COMMENT='')=1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='exam_paper' AND COLUMN_NAME='updated_by' AND DATA_TYPE='bigint' AND COLUMN_TYPE='bigint unsigned' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL AND EXTRA='' AND GENERATION_EXPRESSION='' AND COLUMN_COMMENT='')=1 THEN 1 ELSE 0 END AS complete;
ALTER TABLE exam_paper ADD COLUMN updated_by BIGINT UNSIGNED NULL AFTER created_by;
